\begin{figure}[t]
  \centering
  \resizebox{\linewidth}{!}{
\begin{tikzpicture}[>=Stealth, node distance=1.8cm,
                      every node/.style={draw, rounded corners, align=center,
                                        minimum width=4.8cm, minimum height=1cm}]
    \node (cons) {Conservation across domains\\(Theorem~\ref{thm:conservation})};
    \node[right=of cons] (neq) {Non-equivocation of TPL\\(Theorem~\ref{thm:non-equivocation})};
    \node[right=of neq] (view) {View correctness for policies\\(Theorem~\ref{thm:view-correctness})};

    \node[below=1.8cm of neq] (exp) {Restricted exposure soundness\\(Theorem~\ref{lem:restricted-exp-soundness})};
    \node[below=1.8cm of view] (priv) {Restricted privacy for public-investors\\(Theorem~\ref{thm:pub-privacy})};

    \draw[->] (cons) -- (neq);
    \draw[->] (neq) -- (view);
    \draw[->] (cons.south) |- (exp.west);
    \draw[->] (neq.south) -- (exp.north);
    \draw[->] (view.south) -- (priv.north);
    \draw[->] (exp.east) -- (priv.west);
  \end{tikzpicture}
}
  \caption{Roadmap of the main reduction arguments.
  Conservation establishes that the total exposure across domains is invariant under honest operation.
  Non-equivocation and view correctness ensure that policy-based views are uniquely determined by the anchored ledger.
  Restricted exposure soundness shows that any adversary who increases exposure must break at least one underlying primitive,
  and the restricted privacy theorem builds on this for a specific public-investor policy.}
  \label{fig:proofs-roadmap}
\end{figure}
